// Valida la entrada del webhook (D14): sin texto valido no
// devuelve items y el flujo se detiene ahi (sin IFs).
const j = $input.first().json || {};
const data = j.body || j;
const texto = String((data && (data.text || data.message)) || '').trim();
if (!texto || texto.length > 4000) {
  return [];
}
return [{ json: {
  ok: true,
  text: texto,
  title: (data && data.title) || '',
  tags: Array.isArray(data && data.tags) ? data.tags : [],
  source: (data && data.source) || 'n8n',
} }];
